+                                                       num_tokens, num_max_tokens_per_rank,
+                                                       num_experts, num_topk,
+                                                       nccl_context->scaleup_rank_idx, nccl_context->num_scaleup_ranks,
+                                                       prologue_num_sms,
+                                                       jit::device_runtime->get_num_smem_bytes(),
+                                                       comm_stream);
+            } else {
+                // Allocate a new tensor
