+                // Elements [local_col_idx*64 + idx_in_group*8, +8) of the row lie in this quant tile / word (see the ctor)
+                const int scale_idx_base = local_col_idx * ELEMS_PER_STEP / F::QUANT_TILE_SIZE;
+                ku::nvbf16x2 data_bf16[4];
+                if constexpr (F::IS_FP4) {
+                    fp4x8_to_bf16x2x4(data, data_bf16);
+                    const uint32_t scale_word = *(const uint32_t*)(scales_row + scale_idx_base);   // Constant offset: the array stays in registers
+                    ku::nvbf16x2 scale = e4m3x2_to_bf16x2(__byte_perm(scale_word, 0, scale_prmt_sel11));   // (s, s)
+                    CUTE_UNROLL
+                    for (int i = 0; i < 4; ++i)
+                        data_bf16[i] = __hmul2(data_bf16[i], scale);   // Exact: e2m1 x e4m3 has at most 2 + 4 significant bits
+                } else {
+                    const int scale_idx = scale_idx_base + (F::QUANT_TILE_SIZE == 32 ? idx_in_group >= GROUP_SIZE / 2 : 0);
+                    CUTE_UNROLL
+                    for (int i = 0; i < 4; ++i) {
+                        data_bf16[i] = fp8x2_to_bf16x2_with_scale(((ku::nve4m3x2*)&data)[i], ((__nv_fp8_e8m0*)scales_row)[scale_idx]);
+                    }
+                }
+                if (local_row_idx == 0 && local_col_idx == 0) {
+                    before_first_store();
+                }
+                asm volatile ("st.weak.shared::cta.b128 [%0], %1;\n"
+                    :
+                    : "r"(dst + dst_offset + local_row_idx * NUM_GROUPS * 128 + local_col_idx * B_TOPK * 128), "q"(*(__int128_t*)data_bf16)
+                );
+            }
+        }
+    }
+};
+
+// Host: TMA tensor map of one CTA's share of the quantized part of a paged KV cache, for gather4. dim0 = DIM0_BYTES of a token
+// starting at byte `cta_byte_offset` (as uint32), dim1 = tokens at F::TMA_K_STRIDE; box = {BOX_BYTES, 1 row}. BOX_BYTES may exceed
+// DIM0_BYTES, the rest of the box is out of bounds and zero-filled by TMA (the padding of the fp4 raw rows, see
+// KVBlockDequantizer) -- or be smaller, reading a box out of a wider view (head128). Each gather4 writes its 4 rows BOX_BYTES
+// apart in shared memory
+template<typename F, int DIM0_BYTES, int BOX_BYTES>
+static CUtensorMap make_kv_quant_part_tensor_map(const char *name, void *kv, int num_blocks, int64_t block_stride_bytes, int row_stride_bytes, int cta_byte_offset) {
+    static_assert(DIM0_BYTES % 4 == 0 && BOX_BYTES % 16 == 0 && BOX_BYTES / 4 <= 256);
+    KU_ASSERT((int64_t)kv % 16 == 0, "The base address of %s (%p) must be 16B aligned", name, kv);
+    KU_ASSERT(row_stride_bytes == F::BYTES_PER_TOKEN, "%s.stride(-2) (%d) must be %d, i.e. each page block in the KV cache must be contiguous", name, row_stride_bytes, F::BYTES_PER_TOKEN);
+    KU_ASSERT(block_stride_bytes % F::TMA_K_STRIDE == 0, "%s.stride(0) (%ld) must be a multiple of %d. Padding might be necessary", name, block_stride_bytes, F::TMA_K_STRIDE);
+    KU_ASSERT((uint64_t)num_blocks * (uint64_t)(block_stride_bytes / F::TMA_K_STRIDE) <= INT32_MAX, "%s: too many rows for the int32 TMA coordinates", name);
+    return ku::make_tensor_map(
+        {(uint64_t)DIM0_BYTES / 4, (uint64_t)num_blocks * (uint64_t)(block_stride_bytes / F::TMA_K_STRIDE)},
+        {(uint64_t)F::TMA_K_STRIDE},
+        {BOX_BYTES / 4, 1},
+        (uint8_t*)kv + cta_byte_offset,
+        CUtensorMapDataType::CU_TENSOR_MAP_DATA_TYPE_UINT32,
+        CUtensorMapSwizzle::CU_TENSOR_MAP_SWIZZLE_NONE,
+        CUtensorMapL2promotion::CU_TENSOR_MAP_L2_PROMOTION_L2_128B
+    );
+}
+
+// Host: the TMA tensor map of the bf16 (RoPE) part of a paged KV cache (F::D_BF16 > 0), for gather4 into a SWIZZLE-byte swizzled tile; box = {BOX_ELEMS, 1 row}
+template<typename F, int BOX_ELEMS, int SWIZZLE>
+static CUtensorMap make_kv_bf16_part_tensor_map(void *kv, int num_blocks, int64_t block_stride_bytes) {
+    static_assert(F::D_BF16 > 0 && (SWIZZLE == 64 || SWIZZLE == 128) && BOX_ELEMS * sizeof(bf16) <= SWIZZLE);
+    return ku::make_tensor_map(
+        {(uint64_t)F::D_BF16, (uint64_t)num_blocks * (uint64_t)(block_stride_bytes / F::TMA_K_STRIDE)},
+        {(uint64_t)F::TMA_K_STRIDE},
+        {BOX_ELEMS, 1},
+        (uint8_t*)kv + (F::TMA_K_STRIDE - 2 * F::D_BF16),   // The bf16 part is the tail of the token's data
+        CUtensorMapDataType::CU_TENSOR_MAP_DATA_TYPE_BFLOAT16,
+        SWIZZLE == 64 ? CUtensorMapSwizzle::CU_TENSOR_MAP_SWIZZLE_64B : CUtensorMapSwizzle::CU_TENSOR_MAP_SWIZZLE_128B,
+        CUtensorMapL2promotion::CU_TENSOR_MAP_L2_PROMOTION_L2_128B
+    );
+}
+
+}

diff --git a/csrc/kernels/sm100/helpers.h b/csrc/kernels/sm100/helpers.h
new file mode 100644
index 000000000..0fd5e0ef5
--- /dev/null
+++ b/csrc/kernels/sm100/helpers.h
@@ -0,0 +1,167 @@
+#pragma once
+
+#include <cuda_fp16.h>
+
+#include <cute/tensor.hpp>
+#include <kerutils/kerutils.cuh>
+
+namespace sm100 {
+
+using namespace cute;
+
+struct bf16x8 {
+    __nv_bfloat162 a01;
+    __nv_bfloat162 a23;
+    __nv_bfloat162 a45;
+    __nv_bfloat162 a67;
+};
+
+CUTE_DEVICE
+int int4_max(int4 t) {
+    return max(max(t.x, t.y), max(t.z, t.w));
+}
+
+CUTE_DEVICE
+int int4_min(int4 t) {
+    return min(min(t.x, t.y), min(t.z, t.w));
+}
+
+struct int32x8_t {
+    int a0, a1, a2, a3, a4, a5, a6, a7;
+};
+
+struct float8 {
+    float2 a01, a23, a45, a67;
+};
+
+// CUDA 13.2 (PTX ISA 9.2) adds a direct {e4m3x2, e2m1x2} -> bf16x2 conversion, i.e.
+// `cvt.rn.bf16x2.e4m3x2` / `cvt.rn.bf16x2.e2m1x2`. Older toolchains only offer the .f16x2
+// destination, so the value has to be widened through the FP32 domain instead.
+#if defined(__CUDACC_VER_MAJOR__) && (__CUDACC_VER_MAJOR__ > 13 || (__CUDACC_VER_MAJOR__ == 13 && __CUDACC_VER_MINOR__ >= 2))
+#define SM100_HAS_NATIVE_BF16X2_CVT 1
+#else
+#define SM100_HAS_NATIVE_BF16X2_CVT 0
+#endif
+
+// 2x f16 -> 2x bf16 (exact: f16 is a subset of f32, and every f16 the KV cache can store is representable in bf16)
+CUTE_DEVICE
+ku::nvbf16x2 f16x2_to_bf16x2(uint32_t f16x2) {
+    return __float22bfloat162_rn(__half22float2(*(__half2*)&f16x2));
+}
+
+// 2x fp8_e4m3 -> 2x bf16, without scaling
+CUTE_DEVICE
+ku::nvbf16x2 fp8x2_to_bf16x2(ku::nve4m3x2 data) {
+    uint32_t out;
+#if SM100_HAS_NATIVE_BF16X2_CVT
+    asm("cvt.rn.bf16x2.e4m3x2 %0, %1;"
+        : "=r"(out)
+        : "h"(*(uint16_t*)&data));
+#else
+    asm("cvt.rn.f16x2.e4m3x2 %0, %1;"
+        : "=r"(out)
+        : "h"(*(uint16_t*)&data));
+    const ku::nvbf16x2 bf16 = f16x2_to_bf16x2(out);
+    out = *(uint32_t*)&bf16;
+#endif
+    return *(ku::nvbf16x2*)&out;
+}
+
+// 1x ue8m0 scale -> 2x bf16 (the same scale in both halves)
+CUTE_DEVICE
+ku::nvbf16x2 ue8m0_to_bf16x2(__nv_fp8_e8m0 scale_e8m0) {
+    uint16_t packed = (uint16_t)(*(uint8_t*)&scale_e8m0) * 0x0101;
+    uint32_t out;
+    asm("cvt.rn.bf16x2.ue8m0x2 %0, %1;"
+        : "=r"(out)
+        : "h"(packed));
+    return *(ku::nvbf16x2*)&out;
+}
+
+// 2x fp8_e4m3 -> 2x bf16, multiplied by an ue8m0 scale
+CUTE_DEVICE
+ku::nvbf16x2 fp8x2_to_bf16x2_with_scale(ku::nve4m3x2 data, __nv_fp8_e8m0 scale_e8m0) {
+    return __hmul2(fp8x2_to_bf16x2(data), ue8m0_to_bf16x2(scale_e8m0));
+}
+
+// 8x fp4_e2m1 (packed in 32 bits, 2 per byte) -> 4x bf16x2
+// Written as one asm block so that ptxas selects the source byte with the .B0-.B3 operand selector of F2FP instead of emitting PRMTs
+CUTE_DEVICE
+void fp4x8_to_bf16x2x4(uint32_t packed, ku::nvbf16x2 *out) {
+    uint32_t o0, o1, o2, o3;
+#if SM100_HAS_NATIVE_BF16X2_CVT
+    asm(
+        "{\n"
+        ".reg .b8 b0, b1, b2, b3;\n"
+        "mov.b32 {b0, b1, b2, b3}, %4;\n"
+        "cvt.rn.bf16x2.e2m1x2 %0, b0;\n"
+        "cvt.rn.bf16x2.e2m1x2 %1, b1;\n"
+        "cvt.rn.bf16x2.e2m1x2 %2, b2;\n"
+        "cvt.rn.bf16x2.e2m1x2 %3, b3;\n"
+        "}\n"
+        : "=r"(o0), "=r"(o1), "=r"(o2), "=r"(o3)
+        : "r"(packed)
+    );
+    out[0] = *(ku::nvbf16x2*)&o0;
+    out[1] = *(ku::nvbf16x2*)&o1;
+    out[2] = *(ku::nvbf16x2*)&o2;
+    out[3] = *(ku::nvbf16x2*)&o3;
+#else
+    asm(
+        "{\n"
+        ".reg .b8 b0, b1, b2, b3;\n"
+        "mov.b32 {b0, b1, b2, b3}, %4;\n"
+        "cvt.rn.f16x2.e2m1x2 %0, b0;\n"
+        "cvt.rn.f16x2.e2m1x2 %1, b1;\n"
+        "cvt.rn.f16x2.e2m1x2 %2, b2;\n"
+        "cvt.rn.f16x2.e2m1x2 %3, b3;\n"
+        "}\n"
+        : "=r"(o0), "=r"(o1), "=r"(o2), "=r"(o3)
+        : "r"(packed)
+    );
+    const ku::nvbf16x2 b0 = f16x2_to_bf16x2(o0), b1 = f16x2_to_bf16x2(o1);
+    const ku::nvbf16x2 b2 = f16x2_to_bf16x2(o2), b3 = f16x2_to_bf16x2(o3);
+    out[0] = b0; out[1] = b1; out[2] = b2; out[3] = b3;
+#endif
+}
+
+// 4x fp8_e4m3 -> 2x bf16x2 without scaling, used for the e4m3 scales of the fp4 KV cache
+CUTE_DEVICE
+void fp8x4_to_bf16x2x2(uint32_t packed, ku::nvbf16x2 *out) {
+    uint32_t o0, o1;
+#if SM100_HAS_NATIVE_BF16X2_CVT
+    asm(
+        "{\n"
+        ".reg .b16 h0, h1;\n"
+        "mov.b32 {h0, h1}, %2;\n"
+        "cvt.rn.bf16x2.e4m3x2 %0, h0;\n"
+        "cvt.rn.bf16x2.e4m3x2 %1, h1;\n"
+        "}\n"
+        : "=r"(o0), "=r"(o1)
+        : "r"(packed)
+    );
+    out[0] = *(ku::nvbf16x2*)&o0;
+    out[1] = *(ku::nvbf16x2*)&o1;
+#else
+    asm(
+        "{\n"
+        ".reg .b16 h0, h1;\n"
+        "mov.b32 {h0, h1}, %2;\n"
+        "cvt.rn.f16x2.e4m3x2 %0, h0;\n"
+        "cvt.rn.f16x2.e4m3x2 %1, h1;\n"
+        "}\n"
+        : "=r"(o0), "=r"(o1)
+        : "r"(packed)
+    );
+    const ku::nvbf16x2 b0 = f16x2_to_bf16x2(o0), b1 = f16x2_to_bf16x2(o1);
+    out[0] = b0; out[1] = b1;
+#endif
+}
+
+// 2x fp8_e4m3 -> bf16x2 without scaling, used for the e4m3 scale of one quant tile of the fp4 KV cache
+CUTE_DEVICE
+ku::nvbf16x2 e4m3x2_to_bf16x2(uint16_t packed) {
+    return fp8x2_to_bf16x2(*(ku::nve4m3x2*)&packed);
+}
+
+}

