+                        uint32_t dst_rank_idx, dst_token_idx, dst_topk_idx;
+                        if constexpr (is_shared_phase) {
+                            dst_rank_idx = sym_buffer.rank_idx;
+                            dst_token_idx = pool_m_idx + m_idx_in_block;
+                            dst_topk_idx = kNumTopk;
