+        const auto combine_load_buffer = utils::PatternVisitor([&](const uint32_t& i) {
+            return math::advance_ptr<uint8_t>(
+                smem_buffer,
+                (epilogue_warp_idx + i * kNumEpilogueWarps) * kInputChunkBytes);
+        });
