+                if (cute::elect_one_sync()) {
+                    cute::tma_store_fence();
+                    ptx::tma_store_1d(
+                        math::advance_ptr(
+                            y,
+                            static_cast<uint64_t>(token_idx) * kCombineOutputHiddenBytes +
+                                output_chunk_byte_offset),
+                        combine_store_buffer, kOutputChunkBytes);
